package com.shazwan.idash;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Real editor interaction, draft isolation, quality debounce, lifecycle and Activity restart. */
public class AppearanceChecks extends Instrumentation {
 LauncherActivity a;int count;Map<String,?> before;SharedPreferences preferences;float oldAnimator;boolean animatorChanged;
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);count++;}
 void ui(Runnable r){Throwable[] error={null};runOnMainSync(()->{try{r.run();}catch(Throwable e){error[0]=e;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 View find(View v,String desc){if(desc.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View result=find(g.getChildAt(i),desc);if(result!=null)return result;}}return null;}
 void shell(String command)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(command);InputStream in=new FileInputStream(fd.getFileDescriptor())){byte[] bytes=new byte[1024];while(in.read(bytes)!=-1){}}}
 void ready()throws Exception{long until=SystemClock.elapsedRealtime()+30000;while((a.appearanceEditor==null||!a.appearanceEditor.cacheReady)&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);check(a.appearanceEditor!=null&&a.appearanceEditor.cacheReady,"preview cache ready");Thread.sleep(500);waitForIdleSync();}
 static void restore(SharedPreferences prefs,Map<String,?> values){SharedPreferences.Editor e=prefs.edit().clear();for(Map.Entry<String,?> entry:values.entrySet()){String k=entry.getKey();Object v=entry.getValue();if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Set)e.putStringSet(k,new HashSet<String>((Set<String>)v));}e.commit();}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  preferences=getTargetContext().getSharedPreferences("idash",0);before=new HashMap<>(preferences.getAll());
  preferences.edit().putString("glass_quality","invalid").putInt("glass_tone",-10).putInt("glass_transparency",900).putInt("glass_tint",30).putInt("glass_reflection",-9).putString("motion","invalid").apply();GlassAppearance sanitized=GlassAppearance.read(getTargetContext());check(sanitized.quality==1&&sanitized.tone==0&&sanitized.transparency==65&&sanitized.tint==4&&sanitized.reflection==0&&sanitized.motion,"corrupt/wrong-type preferences safely default or clamp");restore(preferences,before);
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));CountDownLatch loaded=new CountDownLatch(1);a.worker.execute(()->a.main.post(loaded::countDown));check(loaded.await(30,TimeUnit.SECONDS),"discovery ready");ui(()->new DashSettings(a).open("Appearance"));ready();AppearanceEditor first=a.appearanceEditor;
  ui(()->{check(!first.dirty,"opening editor has no unsaved changes");check(!first.applyButton.isEnabled(),"Apply disabled when unchanged");for(String desc:new String[]{"Appearance Reset","Appearance Cancel","Appearance Apply","Appearance Glass style","Appearance Glass tint","Appearance transparency","Preview example button"}){View v=find(first.root,desc);check(v!=null&&v.getWidth()>=a.dp(48)&&v.getHeight()>=a.dp(48),"48dp target: "+desc);Rect rect=new Rect();check(v.getGlobalVisibleRect(rect)&&rect.height()==v.getHeight(),"not clipped: "+desc);}Spinner style=(Spinner)find(first.root,"Appearance Glass style");style.setSelection(1);});ui(()->check(first.draft.tone==1,"Light choice updates draft"));check(!preferences.getBoolean("glass_customized",false)||GlassAppearance.read(a).tone==first.saved.tone,"choice does not save");
  int builds=first.preparedCount;Bitmap cache=first.cache.frame.bitmap;ui(()->{SeekBar slider=(SeekBar)find(first.root,"Appearance transparency");for(int i=0;i<50;i++)slider.setProgress(i%21);check(first.dirty,"slider makes draft dirty");check(first.cache.frame.bitmap==cache,"slider reuses bitmap");});Thread.sleep(400);check(first.preparedCount==builds,"slider never starts a cache rebuild");ui(first::cancel);check(first.closed&&first.cache.frame.bitmap==null&&a.appearanceEditor==null,"Cancel releases preview cache and owner");check(!preferences.contains("glass_transparency")||preferences.getInt("glass_transparency",20)==(before.containsKey("glass_transparency")?(Integer)before.get("glass_transparency"):20),"Cancel preserves saved transparency");
  ui(()->new DashSettings(a).open("Appearance"));ready();AppearanceEditor editor=a.appearanceEditor;ui(()->{editor.reset();check(editor.draft.quality==1&&editor.draft.tone==0&&editor.draft.transparency==45,"Reset uses safe BALANCED defaults");});check(!preferences.contains("glass_tint")||preferences.getInt("glass_tint",0)==(before.containsKey("glass_tint")?(Integer)before.get("glass_tint"):0),"Reset is draft-only");
  ui(()->editor.selectTab(1));for(int quality:new int[]{0,2,1}){final int q=quality;ui(()->((Spinner)find(editor.root,"Appearance Glass quality")).setSelection(q));ready();ui(()->{check(editor.draft.quality==q,"quality selection actual value");check(editor.cache.frame.bitmap!=null&&Math.max(editor.cache.frame.bitmap.getWidth(),editor.cache.frame.bitmap.getHeight())<=IosStyle.FROST_EDGE[q],"quality cache bound");});}
  int beforeBurst=editor.preparedCount;ui(()->{for(int i=0;i<18;i++)editor.change(2,i%2);editor.change(2,2);});ready();check(editor.preparedCount-beforeBurst==1,"rapid quality changes debounce to one bitmap build");ui(()->{editor.change(0,2);editor.change(3,3);editor.change(4,0);editor.change(5,0);});ready();final int chosenQuality=editor.draft.quality;ui(()->find(editor.root,"Appearance Apply").performClick());check(editor.closed,"Apply closes old preview resources");check(GlassAppearance.read(a).customized&&GlassAppearance.read(a).tone==2&&GlassAppearance.read(a).quality==chosenQuality,"Apply saves validated preferences");check(IosStyle.backdrop(a).frame.quality==chosenQuality,"Apply publishes prepared quality cache without another decode");
  ready();ui(()->{a.appearanceEditor.change(0,1);a.appearanceEditor.apply();a.controlCenter();});Thread.sleep(450);ui(()->{check(a.quickControls.mediaControl.title.getCurrentTextColor()==IosStyle.INK,"Light Glass updates real Control Center text without restart");check(a.quickControls.mediaControl.playGlyph.color==IosStyle.INK,"Light Glass updates actual control icon foreground");a.quickControls.close();});
  ui(()->a.finish());a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ui(()->new DashSettings(a).open("Appearance"));ready();ui(()->{check(a.appearanceEditor.saved.tone==1&&a.appearanceEditor.saved.tint==3&&!a.appearanceEditor.saved.motion,"saved appearance survives Activity restart");AppearanceEditor e=a.appearanceEditor;e.pause();check(!e.active,"background pauses preview");e.resume();check(e.active,"return resumes preview");e.selectTab(0);});
  oldAnimator=android.provider.Settings.Global.getFloat(a.getContentResolver(),android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,1);shell("settings put global animator_duration_scale 0");animatorChanged=true;ui(()->{AppearanceEditor e=a.appearanceEditor;e.selectTab(1);((Switch)find(e.root,"Appearance animation")).setChecked(true);check(!e.draft.animationAllowed(a)&&e.sample.getAlpha()==1,"Android reduced motion suppresses preview animation");});shell("settings put global animator_duration_scale "+oldAnimator);animatorChanged=false;
  int width=a.getResources().getDisplayMetrics().widthPixels,height=a.getResources().getDisplayMetrics().heightPixels;Bitmap original=a.wallpaperBitmap;GlassBackdrop.Frame originalFrame=IosStyle.backdrop(a).frame;
  for(int palette=0;palette<2;palette++){Bitmap wall=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(wall);Paint p=new Paint(3);p.setShader(new LinearGradient(0,0,width,height,palette==0?0xff102238:0xffffe0ec,palette==0?0xff355d7b:0xffb9dafa,Shader.TileMode.CLAMP));c.drawPaint(p);GlassBackdrop.Frame frame=GlassBackdrop.prepare(wall,1);final int light=palette==0?2:1;ui(()->{a.wallpaperBitmap=wall;a.updateBackdrop();IosStyle.publishGlass(a,frame);a.appearanceEditor.change(0,light);a.appearanceEditor.change(2,1);a.appearanceEditor.selectTab(0);});ready();Thread.sleep(450);Bitmap shot=getUiAutomation().takeScreenshot();check(shot!=null&&shot.getWidth()==width,"real editor screenshot");try(OutputStream out=new FileOutputStream(new File(a.getFilesDir(),"appearance-"+(palette==0?"dark":"light")+"-"+width+"x"+height+".png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);}shot.recycle();ui(()->a.appearanceEditor.selectTab(1));Thread.sleep(250);ui(()->{for(String desc:new String[]{"Appearance Glass quality","Appearance Reflection","Appearance animation"}){View v=find(a.appearanceEditor.root,desc);Rect r=new Rect();check(v!=null&&v.getHeight()>=a.dp(48)&&v.getWidth()>=a.dp(48)&&v.getGlobalVisibleRect(r)&&r.height()==v.getHeight(),"Effects target visible: "+desc);}});Bitmap effects=getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(a.getFilesDir(),"appearance-effects-"+(palette==0?"dark":"light")+"-"+width+"x"+height+".png"))){effects.compress(Bitmap.CompressFormat.PNG,100,out);}effects.recycle();}
  ui(()->{a.appearanceEditor.close();a.wallpaperBitmap=original;a.updateBackdrop();IosStyle.publishGlass(a,originalFrame);});
  result.putString("stream","PASS: "+count+" appearance draft/cache/lifecycle/UI checks\n");code=Activity.RESULT_OK;
 }catch(Throwable error){try{android.graphics.Bitmap failure=getUiAutomation().takeScreenshot();if(failure!=null){try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getFilesDir(),"appearance-failure.png"))){failure.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}failure.recycle();}}catch(Exception ignored){}result.putString("stream","FAIL after "+count+": "+error+"\n");}finally{if(animatorChanged)try{shell("settings put global animator_duration_scale "+oldAnimator);}catch(Exception ignored){}if(preferences!=null&&before!=null)restore(preferences,before);if(a!=null)ui(()->{if(a.appearanceEditor!=null)a.appearanceEditor.close();a.finish();});}finish(code,result);}
}
